<template><section class="ops-panel"><div class="ops-toolbar"><div><h2>独立凭据库存</h2><p class="ops-muted">已分配凭据属于指定用户；工作空间使用其负责人的凭据。秘密只写入托管存储，不支持回显。</p></div><div class="ops-actions"><el-button v-if="can('credentials.assign')" size="small" @click="open('assign')">分配给用户</el-button><el-button v-if="can('credentials.rotate')" size="small" @click="open('rotate')">轮换用户凭据</el-button><el-button v-if="can('credentials.write')" type="primary" size="small" @click="open('create')">入库凭据</el-button><el-button size="small" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><section v-if="inventory" class="ops-panel"><h3>库存水位与待开通队列</h3><p class="ops-muted">一人一把托管密钥，库存耗尽会让新用户停在“待开通”。按供应商监控水位并补齐等待队列。</p><el-alert v-for="alert in inventory.alerts" :key="alert.code + (alert.provider || '')" :title="alertTitle(alert)" :type="alert.code === 'CREDENTIAL_INVENTORY_LOW' ? 'warning' : 'info'" :closable="false" /><el-table :data="inventory.providers" empty-text="暂无凭据库存记录"><el-table-column prop="provider" label="供应商" min-width="120" /><el-table-column prop="inventory" label="可分配库存" width="110" /><el-table-column prop="active" label="已分配" width="100" /><el-table-column prop="pendingUsers" label="待开通用户" width="120" /><el-table-column label="水位" width="110"><template slot-scope="s"><el-tag :type="s.row.lowInventory ? 'warning' : 'success'" size="small">{{ s.row.lowInventory ? '低于阈值' : '正常' }}</el-tag></template></el-table-column></el-table><el-table :data="pending" v-loading="pendingLoading" empty-text="没有等待凭据的用户"><el-table-column prop="userId" label="待开通用户 ID" width="150" /><el-table-column prop="username" label="账号" min-width="150" /><el-table-column prop="provider" label="供应商" min-width="120" /><el-table-column prop="registeredAt" label="注册时间" min-width="170" /><el-table-column label="操作" width="110"><template slot-scope="s"><el-button v-if="can('credentials.assign')" type="text" @click="open('assign', s.row)">补齐凭据</el-button></template></el-table-column></el-table></section><el-table :data="rows" v-loading="loading" empty-text="暂无凭据；服务不会借用其他用户的密钥"><el-table-column prop="provider" label="供应商" min-width="130" /><el-table-column prop="upstreamId" label="上游标识" min-width="160" /><el-table-column prop="masked" label="密钥标记" min-width="150" /><el-table-column prop="userId" label="归属用户" min-width="130" /><el-table-column prop="status" label="状态" width="120" /><el-table-column prop="version" label="版本" width="80" /><el-table-column label="操作" width="85"><template slot-scope="s"><el-button v-if="can('credentials.revoke') && s.row.status !== 'REVOKED'" type="text" @click="open('revoke', s.row)">吊销</el-button></template></el-table-column></el-table><el-dialog :title="title" :visible.sync="dialog" width="min(540px,92vw)" :close-on-click-modal="false" @closed="clearSecret"><el-form label-width="100px" autocomplete="off"><el-form-item v-if="action !== 'revoke'" label="供应商"><el-select v-model="form.provider"><el-option label="DeepSeek" value="DEEPSEEK" /><el-option label="火山引擎" value="VOLCENGINE" /></el-select></el-form-item><template v-if="action === 'create'"><el-form-item label="上游标识"><el-input v-model="form.upstreamId" placeholder="非秘密的 Key ID 或库存标签" /></el-form-item><el-form-item label="密钥字段"><el-input v-model="form.secretText" type="textarea" :rows="5" autocomplete="off" spellcheck="false"  :placeholder="secretPlaceholder" /><p class="ops-muted">{{ form.provider === "VOLCENGINE" ? "火山方舟与豆包语音使用独立鉴权字段；缺少对应字段时该能力不可用。" : "填写 DeepSeek 官方 API Key。" }} 秘密加密托管，不回显。</p></el-form-item></template><el-form-item v-if="action === 'assign' || action === 'rotate'" label="用户 ID"><el-input v-model="form.userId" /></el-form-item><el-form-item v-if="action === 'revoke'" label="吊销原因"><el-input v-model="form.reason" type="textarea" :rows="3" /></el-form-item></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认{{ title }}</el-button></span></el-dialog></section></template>
<script>
import { operations } from '@/apis/platform';
import { hasPermission } from '@/security/session';
import { newOperationId } from '@/utils/allowance';
export default {
  data() { return { rows: [], loading: false, error: '', dialog: false, action: 'create', form: {}, saving: false, saveError: '', inventory: null, pending: [], pendingLoading: false }; },
  computed: { secretPlaceholder() { return this.form.provider === 'VOLCENGINE' ? '{"llm_api_key":"方舟模型凭据","speech_api_key":"豆包语音凭据"}' : '{"api_key":"DeepSeek 凭据"}'; }, title() { return ({ create: '凭据入库', assign: '分配凭据', rotate: '轮换凭据', revoke: '吊销凭据' })[this.action]; } },
  created() { this.load(); }, beforeDestroy() { this.clearSecret(); },
  methods: {
    can(permission) { return hasPermission(this.$store.state.userInfo, permission); },
    alertTitle(alert) { return alert.code === 'CREDENTIAL_INVENTORY_LOW' ? `${alert.provider} 可分配库存 ${alert.inventory} 已低于阈值 ${alert.minimum}` : `${alert.provider} 有 ${alert.waiting} 个用户等待凭据`; },
    async load() { this.loading = true; this.error = ''; try { const result = await operations.credentials({ page: 1, limit: 100 }); this.rows = result.list || []; await Promise.all([this.loadInventory(), this.loadPending()]); } catch (error) { this.error = error.message; } finally { this.loading = false; } },
    async loadInventory() { try { this.inventory = await operations.credentialInventory(); } catch (_) { this.inventory = null; } },
    async loadPending() { this.pendingLoading = true; try { const result = await operations.credentialPending({ page: 1, limit: 50 }); this.pending = result.list || []; } catch (_) { this.pending = []; } finally { this.pendingLoading = false; } },
    open(action, row = {}) { this.action = action; this.form = { requestId: newOperationId(), id: row.id || row.credentialId, provider: row.provider || 'DEEPSEEK', upstreamId: '', userId: row.userId || '', reason: '', secretText: '' }; this.saveError = ''; this.dialog = true; },
    clearSecret() { this.form.secretText = ''; },
    async save() { if (this.saving) return; this.saveError = ''; let secrets;
      if (this.action === 'create') { try { secrets = JSON.parse(this.form.secretText); if (!secrets || Array.isArray(secrets) || typeof secrets !== 'object' || !Object.keys(secrets).length || Object.values(secrets).some(value => typeof value !== 'string' || !value.trim())) throw new Error(); } catch (_) { this.saveError = '密钥字段需要非空 JSON 对象，每个字段值为字符串'; return; } if (!this.form.upstreamId.trim()) { this.saveError = '请填写上游标识'; return; } }
      if (['assign','rotate'].includes(this.action) && !/^\d+$/.test(String(this.form.userId))) { this.saveError = '请填写有效用户 ID'; return; }
      if (this.action === 'revoke' && !this.form.reason.trim()) { this.saveError = '请填写吊销原因'; return; }
      this.saving = true; try { if (this.action === 'create') await operations.addCredential({ provider: this.form.provider, upstreamId: this.form.upstreamId.trim(), secrets }); else if (this.action === 'rotate') await operations.rotateCredential({ requestId: this.form.requestId, userId: this.form.userId, provider: this.form.provider }); else if (this.action === 'assign') await operations.assignCredential({ requestId: this.form.requestId, userId: this.form.userId, provider: this.form.provider }); else await operations.revokeCredential(this.form.id, this.form.reason); this.clearSecret(); this.dialog = false; await this.load(); } catch (error) { this.saveError = error.message; } finally { this.saving = false; secrets = null; }
    },
  },
};
</script>
